#!/usr/bin/env bash
# DREAM v03 "Ignition" · batch 4: nine 4 s Seedance 2.5 1080p clips designed around their cuts. Saves nodes only.
set -euo pipefail
cd "$(dirname "$0")/../.."
J="python3 tools/jm.py film02/jimeng-state.json"
LOCK="【产品身份锁定】画面中的飞行器是参考图中的同一台 CoolFly Dream 单人电动飞行器：橙色整流罩带两道白色竖条纹和「05」号码，深灰色钢管防滚架，白色座椅，四根碳纤维机臂，每根机臂末端上下各一组黑色电机和两叶碳纤维螺旋桨。全程不增减机臂、电机、螺旋桨，不改变比例和涂装，不变形，不出现第二台飞行器，不出现任何文字、字幕或水印。"
HUMAN="人物必须像真人实拍：真实皮肤、自然细微的动作，不僵硬、不变脸、不出现多余的手指或五官变形。"
CLEAN="不出现突然亮起的光斑、镜头光晕或闪烁，曝光稳定。真实电影摄影质感。"
PILOT="驾驶员全程坐在座椅上，头盔面罩遮住脸。"

$J vid VN1 --title "VN1 video · 机库顶灯依次亮起" --mode m2v --ref N1 --ref G-v1-front34 --dur 4 --prompt "参考 {{node:$(python3 -c "import json;print(json.load(open('film02/jimeng-state.json'))['nodes']['N1']['nodeId'])")}} 的机库场景和构图。$LOCK 0.0 秒画面几乎全黑，只能隐约看到飞行器的轮廓；从 0.3 秒开始，天花板上的长条 LED 灯管从远处向镜头方向一排接一排地依次点亮，每 0.5 秒亮一排，每亮一排，橙色整流罩上的高光条就向前滑动一段，水泥地面的反光随之出现；到 3.0 秒全部点亮，最终画面接近参考图。镜头低机位，极其缓慢地推近。$CLEAN"
$J vid VN2 --title "VN2 video · 剪影转头" --first N2 --dur 4 --prompt "以首帧为起点，镜头锁定。驾驶员戴着头盔的侧面剪影站在饱和的橙色背景光前，0.5–3.0 秒头部缓慢而自然地转向镜头约 20 度，再微微低头，头盔边缘的轮廓光随转动在曲面上平滑滑动；背景橙光保持稳定。人物几乎全黑，看不到面部。$HUMAN $CLEAN"
$J vid VN3 --title "VN3 video · 眼睛眨眼与橙光" --first N3 --dur 4 --prompt "以首帧为起点，镜头锁定的微距特写。0.6 秒时眼睛自然地眨一次；1.5–2.8 秒一道细长的橙色光从左向右扫过，在虹膜和角膜上留下移动的反光，瞳孔随光线轻微收缩；随后眼神坚定地看向前方。真实的皮肤纹理和睫毛，动作细微自然。$HUMAN $CLEAN"
$J vid VN4 --title "VN4 video · 头顶掠过" --first N4 --dur 4 --prompt "$LOCK $PILOT 以首帧为起点，摄影机在悬崖顶岩石上低机位仰拍，固定不动。飞行器高速朝镜头方向飞来，越来越近，在 3.0–3.8 秒从镜头正上方呼啸掠过，机腹、镂空底盘和机臂在最后 0.6 秒遮满整个画面并带有强烈的运动模糊（用于转场）。螺旋桨呈半透明旋转虚影。$CLEAN"
$J vid VN5 --title "VN5 video · 贴海高速追拍" --first N5 --dur 4 --prompt "$LOCK $PILOT 以首帧为起点：飞行器在离海面约 3 米处高速向前飞行，下洗气流在海面上犁出白色水雾尾迹；摄影机贴着水面从侧后方同速追拍，近处海浪高速掠过、带强烈运动模糊；最后 1 秒飞行器加速向画面右前方冲出，镜头跟不上。螺旋桨呈半透明旋转虚影。$CLEAN"
$J vid VN6 --title "VN6 video · 俯拍越过海岸线" --first N6 --dur 4 --prompt "$LOCK $PILOT 以首帧为起点，摄影机在高空垂直向下俯拍，与飞行器同速平移跟随：飞行器从海面上方飞越海岸线，向礁石陆地方向前进，它的影子在礁石上快速滑过，下方浪花拍打礁石。俯拍角度和高度保持不变。螺旋桨呈半透明旋转虚影。$CLEAN"
$J vid VN7 --title "VN7 video · 侧倾绕海蚀柱 甩镜" --first N7 --dur 4 --prompt "$LOCK $PILOT 以首帧为起点：飞行器侧倾约 20 度，绕过高耸的黑色海蚀柱转弯，下方海浪翻涌；摄影机用长焦从侧面跟摇，背景带横向运动模糊；最后 0.5 秒镜头快速甩向右侧（甩镜），整个画面形成强烈的横向运动模糊（用于转场）。螺旋桨呈半透明旋转虚影。$CLEAN"
$J vid VN8 --title "VN8 video · 迎面冲镜 掠过" --first N8 --dur 4 --prompt "$LOCK $PILOT 以首帧为起点：飞行器在海面上方迎面高速冲向镜头，越来越大，在 3.0–3.7 秒从镜头上方掠过，机腹和气流在最后 0.5 秒遮满画面并带强烈运动模糊（用于转场）。摄影机固定不动。螺旋桨呈半透明旋转虚影。$CLEAN"
